def sort_batteries(batteries):
    row = []
    for battery in batteries:
        row.append(battery)
    settled = 0
    selected = []
    for start in range(len(row) - 1):
        min_index = start
        for index in range(start + 1, len(row)):
            smaller = row[index][1] < row[min_index][1]
            if smaller:
                min_index = index
        selected.append(row[min_index][0])
        if min_index != start:
            held = row[start]
            row[start] = row[min_index]
            row[min_index] = held
        settled = start + 1
    settled = len(row)
    return [selected, row]
